    ],
    "N": [
      "Ovarian cyst (rupture/hemorrhage) or adnexal mass: Can produce lower abdominal pain and acute/subacute nausea; may cause spotting. Less likely without acute severe focal pain or known mass but possible."
    ],
    "D": [
      "Constipation/functional bowel pain: She had constipation ~1 week ago which recently resolved; constipation can produce suprapubic discomfort and nausea.",
      "Irritable bowel / transient gastroenteritis: Could explain nausea and abdominal ache, though diarrhoea/vomiting absent."
    ],
    "I2": [
      "Contraceptive implant–related bleeding: Implanon commonly causes irregular bleeding/spotting which could explain the pink urine/spotting; implant failure (pregnancy) is rare but possible and would be iatrogenic in the sense of contraception-related issues."
    ],
    "C": [
      "Congenital urinary tract anomaly (e.g., vesicoureteral reflux with recurrent UTIs): Unlikely new presentation but can predispose to UTIs causing suprapubic pain."
